const formatRupiah = (value: string) => {
    const rawNumber = value.replace(/\D/g, "")
    if (!rawNumber) return ""
    const formatted = parseInt(rawNumber, 10).toLocaleString("id-ID")
    return `Rp ${formatted}`
}

