    const updateHeroBannerLive = broadcastHeroBannerDraft;

    // Helper to compress/resize high-res image files into a fast lightweight web-safe dataUrl for preview and storage
    const compressImageForPreview = (file: File): Promise<string> => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const dataUrl = e.target?.result as string;
                if (!dataUrl) {
                    resolve("");
                    return;
                }
                const img = new window.Image();
                img.onload = () => {
                    const maxDim = 1200;
                    let w = img.width;
                    let h = img.height;
                    if (w > maxDim || h > maxDim) {
                        if (w > h) {
                            h = Math.round((h * maxDim) / w);
                            w = maxDim;
                        } else {
                            w = Math.round((w * maxDim) / h);
                            h = maxDim;
                        }
                    }
                    const canvas = document.createElement("canvas");
                    canvas.width = w;
                    canvas.height = h;
                    const ctx = canvas.getContext("2d");
                    if (ctx) {
                        ctx.drawImage(img, 0, 0, w, h);
                        const format = file.type === "image/png" ? "image/png" : "image/jpeg";
                        const compressed = canvas.toDataURL(format, 0.85);
                        resolve(compressed);
                    } else {
                        resolve(dataUrl);
                    }
                };
                img.onerror = () => resolve(dataUrl);
                img.src = dataUrl;
            };
            reader.onerror = () => resolve("");
            reader.readAsDataURL(file);
        });
    };

