    const handleAddSolusiCard = () => {
        const newIdx = solusiBisnisCards.length + 1;
        const sampleImg = `/images/solusi/solusi-${((newIdx - 1) % 4) + 1}.jpg`;
        const newCard: SolusiBisnisCard = {
            id: `card-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
            title: "Mulai Brand Obat Herbal Baru",
            desc: "Wujudkan produk impian Anda meski tanpa pengalaman. Kami bantu dari konsep, formulasi, hingga legalitas (BPOM & Halal) siap rilis.",
            image: sampleImg,
        };
        const newCards = [...solusiBisnisCards, newCard];
        setSolusiBisnisCards(newCards);
        updateSolusiBisnisLive({ cards: newCards });
        toast.add({ title: `Modul kartu #${newCards.length} berhasil ditambahkan!`, type: 'success' });
    };

    const handleDuplicateSolusiCard = (index: number) => {
        const target = solusiBisnisCards[index];
        const duplicatedCard: SolusiBisnisCard = {
            ...target,
            id: `card-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
            title: `${target.title} (Salinan)`,
        };
        const newCards = [...solusiBisnisCards];
        newCards.splice(index + 1, 0, duplicatedCard);
        setSolusiBisnisCards(newCards);
        updateSolusiBisnisLive({ cards: newCards });
        toast.add({ title: `Modul kartu #${index + 1} berhasil diduplikasi!`, type: 'success' });
    };

    const handleMoveSolusiCard = (index: number, direction: 'up' | 'down') => {
        if (direction === 'up' && index === 0) return;
        if (direction === 'down' && index === solusiBisnisCards.length - 1) return;
        const targetIndex = direction === 'up' ? index - 1 : index + 1;
        const newCards = [...solusiBisnisCards];
        const temp = newCards[index];
        newCards[index] = newCards[targetIndex];
        newCards[targetIndex] = temp;
        setSolusiBisnisCards(newCards);
        updateSolusiBisnisLive({ cards: newCards });
    };

    const handleDeleteSolusiCard = (index: number) => {
        if (solusiBisnisCards.length <= 1) {
            toast.add({ title: "Minimal harus ada 1 kartu solusi bisnis", type: 'error' });
            return;
        }
        const newCards = solusiBisnisCards.filter((_, i) => i !== index);
        setSolusiBisnisCards(newCards);
        updateSolusiBisnisLive({ cards: newCards });
        toast.add({ title: `Modul kartu #${index + 1} berhasil dihapus`, type: 'info' });
    };

