                    if (parsed.bgColor) setTopbarBgColor(parsed.bgColor);
                    if (parsed.menuTextColor) setTopbarMenuTextColor(parsed.menuTextColor);
                    if (parsed.menuActiveColor) setTopbarMenuActiveColor(parsed.menuActiveColor);
                    if (parsed.menuTextSize) setTopbarMenuTextSize(Number(parsed.menuTextSize));
                    if (parsed.menuFont) setTopbarMenuFont(parsed.menuFont);
