                                                                    "py-2 text-xs font-medium border text-center transition-colors cursor-pointer",
                                                                    videoProfilPosition === "right"
                                                                        ? "bg-primary text-primary-foreground border-primary"
                                                                        : "bg-background border-primary/20 text-muted-foreground hover:bg-muted"
